    #[test]
    fn test_dipole_field_1_over_r_cubed_decay() {
        let dipole_pos = [0.0, 0.0, 0.0];
        let moment = [0.0, 0.0, 1e-9]; // z-oriented dipole
        let orient = [0.0, 0.0, 1.0]; // Sensor oriented along z

        // Measure at two distances along x-axis
        // For a z-dipole measured along z at a point on x-axis:
        // Q.rhat = 0, Q.n = 1e-9, so B = prefactor * (0 - Q.n) = -mu0/(4pi r^3) * Q_z
        let r1 = 0.05;
        let r2 = 0.10;

        let b1 = MegProcessor::magnetic_dipole_field(
            dipole_pos,
            moment,
            [r1, 0.0, 0.0],
            orient,
        );
        let b2 = MegProcessor::magnetic_dipole_field(
            dipole_pos,
            moment,
            [r2, 0.0, 0.0],
            orient,
        );

        // Both should be non-zero
        assert!(b1.abs() > 1e-20, "B1 should be non-zero, got {}", b1);
        assert!(b2.abs() > 1e-20, "B2 should be non-zero, got {}", b2);

        // B should scale as 1/r^3, so |B1|/|B2| ~ (r2/r1)^3 = 8
        let ratio = b1 / b2;
        assert!(
            (ratio - 8.0).abs() < 0.01,
            "1/r^3 decay: ratio = {}, expected 8.0",
            ratio
        );
    }

