    #[test]
    fn test_forward_model_consistency() {
        let (positions, orientations) = test_sensor_array(16, 0.12);
        let source = DipoleSource {
            position: [0.0, 0.0, 0.0],
            moment: [1e-9, 0.0, 0.0],
            goodness_of_fit: 1.0,
        };

        let predicted = MegProcessor::forward_model(&source, &positions, &orientations);
        assert_eq!(predicted.len(), 16);

        // Verify each element matches direct computation
        for i in 0..16 {
            let direct = MegProcessor::magnetic_dipole_field(
                source.position,
                source.moment,
                positions[i],
                orientations[i],
            );
            let diff = (predicted[i] - direct).abs();
            let scale = predicted[i].abs().max(1e-30);
            assert!(
                diff < scale * 1e-10,
                "Forward model inconsistent at sensor {}: diff={:.2e}",
                i,
                diff
            );
        }
    }

    #[test]
    fn test_forward_model_superposition() {
        let (positions, orientations) = test_sensor_array(8, 0.12);

        let s1 = DipoleSource {
            position: [0.0, 0.0, 0.0],
            moment: [1e-9, 0.0, 0.0],
            goodness_of_fit: 1.0,
        };
        let s2 = DipoleSource {
            position: [0.0, 0.0, 0.0],
            moment: [0.0, 1e-9, 0.0],
            goodness_of_fit: 1.0,
        };
        let s_combined = DipoleSource {
            position: [0.0, 0.0, 0.0],
            moment: [1e-9, 1e-9, 0.0],
            goodness_of_fit: 1.0,
        };

        let f1 = MegProcessor::forward_model(&s1, &positions, &orientations);
        let f2 = MegProcessor::forward_model(&s2, &positions, &orientations);
        let fc = MegProcessor::forward_model(&s_combined, &positions, &orientations);

        for i in 0..8 {
            let diff = (fc[i] - (f1[i] + f2[i])).abs();
            let scale = fc[i].abs().max(1e-30);
            assert!(
                diff < scale * 1e-10,
                "Forward model should be linear (superposition): diff={:.2e}, scale={:.2e}",
                diff,
                scale
            );
        }
    }

