    #[test]
    fn test_dipole_fit_recovery() {
        let (positions, orientations) = test_sensor_array(32, 0.12);

        // Create a known source
        let true_source = DipoleSource {
            position: [0.02, 0.01, 0.0],
            moment: [1e-9, 0.5e-9, 0.0],
            goodness_of_fit: 1.0,
        };

        // Generate measurements
        let measurements =
            MegProcessor::forward_model(&true_source, &positions, &orientations);

        // Create a grid that includes the true position
        let mut grid = Vec::new();
        for ix in -3..=3 {
            for iy in -3..=3 {
                grid.push([ix as f64 * 0.01, iy as f64 * 0.01, 0.0]);
            }
        }

        let fitted = MegProcessor::dipole_fit(&measurements, &positions, &orientations, &grid);

        // GOF should be high (close to 1)
        assert!(
            fitted.goodness_of_fit > 0.95,
            "GOF = {} should be > 0.95",
            fitted.goodness_of_fit
        );

        // Position should match the nearest grid point to [0.02, 0.01, 0.0]
        let error_mm = SourceLocalizer::equivalent_current_dipole_error(
            true_source.position,
            fitted.position,
        );
        // Grid spacing is 10mm, so error should be within grid spacing
        assert!(
            error_mm < 15.0,
            "Localization error = {:.1} mm, expected < 15 mm",
            error_mm
        );
    }

