    #[test]
    fn test_minimum_norm_basic() {
        // Simple 2-sensor, 3-source problem
        let lead_field = vec![
            vec![1.0, 0.0],   // Source 0 contributes to sensor 0
            vec![0.0, 1.0],   // Source 1 contributes to sensor 1
            vec![0.5, 0.5],   // Source 2 contributes equally
        ];

        let measurements = vec![1.0, 1.0];
        let result = MegProcessor::minimum_norm_estimate(&measurements, &lead_field, 0.01);

        assert_eq!(result.len(), 3);
        // All source amplitudes should be reasonable
        for &v in &result {
            assert!(v.is_finite(), "MNE result should be finite");
        }
    }

    #[test]
    fn test_minimum_norm_regularization() {
        let lead_field = vec![vec![1.0, 0.0], vec![0.0, 1.0]];
        let measurements = vec![1.0, 1.0];

        // Larger lambda = more regularization = smaller norm
        let result_low = MegProcessor::minimum_norm_estimate(&measurements, &lead_field, 0.001);
        let result_high = MegProcessor::minimum_norm_estimate(&measurements, &lead_field, 10.0);

        let norm_low: f64 = result_low.iter().map(|x| x * x).sum();
        let norm_high: f64 = result_high.iter().map(|x| x * x).sum();

        assert!(
            norm_low > norm_high,
            "Higher regularization should produce smaller norm estimate"
        );
    }

