    #[test]
    fn test_dipole_scanning_finds_source() {
        let (positions, orientations) = test_sensor_array(24, 0.12);

        let true_source = DipoleSource {
            position: [0.03, 0.0, 0.0],
            moment: [1e-9, 0.0, 0.0],
            goodness_of_fit: 1.0,
        };

        let measurements =
            MegProcessor::forward_model(&true_source, &positions, &orientations);

        let mut grid = Vec::new();
        for ix in -5..=5 {
            for iy in -5..=5 {
                grid.push([ix as f64 * 0.01, iy as f64 * 0.01, 0.0]);
            }
        }

        let results =
            SourceLocalizer::dipole_scanning(&measurements, &grid, &positions, &orientations);

        // Best result should be at or near the true source
        let (best_gof, best_pos) = results[0];
        assert!(best_gof > 0.9, "Best GOF = {}, should be > 0.9", best_gof);

        let error =
            SourceLocalizer::equivalent_current_dipole_error(true_source.position, best_pos);
        assert!(
            error < 15.0,
            "Best position error = {:.1} mm, should be < 15 mm (grid spacing = 10 mm)",
            error
        );
    }

    #[test]
    fn test_dipole_scanning_sorted_by_gof() {
        let (positions, orientations) = test_sensor_array(16, 0.12);

        let source = DipoleSource {
            position: [0.02, 0.0, 0.0],
            moment: [1e-9, 0.0, 0.0],
            goodness_of_fit: 1.0,
        };

        let measurements =
            MegProcessor::forward_model(&source, &positions, &orientations);

        let grid = vec![[0.0, 0.0, 0.0], [0.02, 0.0, 0.0], [0.05, 0.05, 0.0]];

        let results =
            SourceLocalizer::dipole_scanning(&measurements, &grid, &positions, &orientations);

        // Should be sorted descending by GOF
        for i in 1..results.len() {
            assert!(
                results[i - 1].0 >= results[i].0,
                "Results should be sorted by descending GOF"
            );
        }
    }

    #[test]
    fn test_localization_error_computation() {
        let true_pos = [0.01, 0.02, 0.03];
        let est_pos = [0.011, 0.021, 0.031];

        let error = SourceLocalizer::equivalent_current_dipole_error(true_pos, est_pos);

        // sqrt(0.001^2 + 0.001^2 + 0.001^2) * 1000 = sqrt(3) * 1 mm ~ 1.73 mm
        let expected = (3.0f64).sqrt();
        assert!(
            (error - expected).abs() < 0.01,
            "Error = {:.2} mm, expected {:.2} mm",
            error,
            expected
        );
    }

