    #[test]
    fn test_music_localization_basic() {
        let n_channels = 8;
        let n_samples = 200;
        let (positions, orientations) = test_sensor_array(n_channels, 0.12);

        // Create data from a single source
        let source = DipoleSource {
            position: [0.03, 0.0, 0.0],
            moment: [1e-9, 0.0, 0.0],
            goodness_of_fit: 1.0,
        };

        let field = MegProcessor::forward_model(&source, &positions, &orientations);

        let mut data = vec![vec![0.0f64; n_samples]; n_channels];
        for ch in 0..n_channels {
            for s in 0..n_samples {
                let t = s as f64 / 1000.0;
                data[ch][s] =
                    field[ch] * (2.0 * PI * 10.0 * t).sin() + 1e-16 * ((s * ch) as f64 * 0.01);
            }
        }

        let cov = SignalPreprocessor::covariance_matrix(&data);

        // Create lead fields at two grid points
        let grid_points: Vec<[f64; 3]> = vec![[0.03, 0.0, 0.0], [-0.03, 0.0, 0.0]];

        let lead_fields: Vec<Vec<Vec<f64>>> = grid_points
            .iter()
            .map(|gp| {
                let lf: Vec<f64> = positions
                    .iter()
                    .zip(orientations.iter())
                    .map(|(sp, so)| {
                        MegProcessor::magnetic_dipole_field(*gp, [1.0, 0.0, 0.0], *sp, *so)
                    })
                    .collect();
                vec![lf]
            })
            .collect();

        let spectrum = SourceLocalizer::music_localization(&cov, &lead_fields, 1);

        assert_eq!(spectrum.len(), 2);
        // MUSIC pseudo-spectrum should be higher at the source location
        assert!(
            spectrum[0] > spectrum[1],
            "MUSIC should peak at source: {:.2e} vs {:.2e}",
            spectrum[0],
            spectrum[1]
        );
    }

    // =====================================================
    // Connectivity tests
    // =====================================================

    #[test]
    fn test_coherence_identical_signals() {
        let sample_rate = 1000.0;
        let fft_size = 64;
        let n = 512; // Multiple segments for Welch averaging
        let signal: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * 40.0 * i as f64 / sample_rate).sin())
            .collect();

        let coh = ConnectivityAnalyzer::coherence(&signal, &signal, sample_rate, fft_size);

        // Find coherence near 40 Hz
        let target_bin = (40.0 / (sample_rate / fft_size as f64)).round() as usize;
        if target_bin < coh.len() {
            assert!(
                coh[target_bin].1 > 0.99,
                "Coherence of identical signals should be ~1.0 at signal frequency, got {}",
                coh[target_bin].1
            );
        }
    }

    #[test]
    fn test_coherence_uncorrelated_signals() {
        let sample_rate = 1000.0;
        let fft_size = 64;
        let n = 1024; // Long signals for proper Welch averaging

        // Two independent pseudo-random signals
        let sig1: Vec<f64> = (0..n)
            .map(|i| {
                ((i as f64 * 7.31 + 2.17).sin() * 43758.5453).fract()
            })
            .collect();
        let sig2: Vec<f64> = (0..n)
            .map(|i| {
                ((i as f64 * 13.97 + 5.43).sin() * 23421.6312).fract()
            })
            .collect();

        let coh = ConnectivityAnalyzer::coherence(&sig1, &sig2, sample_rate, fft_size);

        // Average coherence of uncorrelated signals should be low
        let avg_coh: f64 = coh.iter().map(|(_, c)| c).sum::<f64>() / coh.len() as f64;
        assert!(
            avg_coh < 0.8,
            "Average coherence of uncorrelated signals should be low, got {}",
            avg_coh
        );
    }

    #[test]
    fn test_imaginary_coherence_zero_lag() {
        let sample_rate = 1000.0;
        let fft_size = 64;
        let n = 512;

        // Identical signals should have zero imaginary coherence (purely real cross-spectrum)
        let signal: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * 40.0 * i as f64 / sample_rate).sin())
            .collect();

        let icoh =
            ConnectivityAnalyzer::imaginary_coherence(&signal, &signal, sample_rate, fft_size);

        // Average imaginary coherence should be near zero for identical signals
        let avg_icoh: f64 = icoh.iter().map(|(_, c)| c).sum::<f64>() / icoh.len().max(1) as f64;
        assert!(
            avg_icoh < 0.05,
            "Imaginary coherence of identical signals should be ~0, got {}",
            avg_icoh
        );
    }

    #[test]
    fn test_imaginary_coherence_phase_shifted() {
        let sample_rate = 1000.0;
        let fft_size = 64;
        let n = 512;

        // Two signals with a phase shift (non-zero imaginary coherence)
        let sig1: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * 40.0 * i as f64 / sample_rate).sin())
            .collect();
        let sig2: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * 40.0 * i as f64 / sample_rate + PI / 4.0).sin())
            .collect();

        let icoh =
            ConnectivityAnalyzer::imaginary_coherence(&sig1, &sig2, sample_rate, fft_size);

        // Should have non-zero imaginary coherence at the signal frequency
        let target_bin = (40.0 / (sample_rate / fft_size as f64)).round() as usize;
        if target_bin < icoh.len() {
            assert!(
                icoh[target_bin].1 > 0.1,
                "Phase-shifted signals should have non-zero imaginary coherence, got {}",
                icoh[target_bin].1
            );
        }
    }

    #[test]
    fn test_phase_transfer_entropy_non_negative() {
        let n = 500;
        let x: Vec<f64> = (0..n).map(|i| (i as f64 * 0.1).sin()).collect();
        let y: Vec<f64> = (0..n).map(|i| (i as f64 * 0.2).cos()).collect();

        let te = ConnectivityAnalyzer::phase_transfer_entropy(&x, &y, 1);
        assert!(
            te >= 0.0,
            "Transfer entropy should be non-negative, got {}",
            te
        );
    }

    #[test]
    fn test_phase_transfer_entropy_directed() {
        // Create a coupled autoregressive system where x -> y
        let n = 5000;
        let lag = 1;

        // Generate x using LCG
        let mut x = vec![0.0f64; n];
        let mut seed: u64 = 12345;
        for i in 0..n {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            x[i] = (seed >> 33) as f64 / (1u64 << 31) as f64;
        }

        // y[t] = x[t-1] deterministically (perfect copy with lag)
        let mut y = vec![0.0f64; n];
        for i in lag..n {
            y[i] = x[i - lag];
        }

        // For identical signals with lag, TE(x->y) should be positive
        // and TE(y->x) at the same lag should be smaller since y doesn't drive x
        let te_x_to_y = ConnectivityAnalyzer::phase_transfer_entropy(&x, &y, lag);
        let te_y_to_x = ConnectivityAnalyzer::phase_transfer_entropy(&y, &x, lag);

        // Both should be non-negative
        assert!(te_x_to_y >= 0.0);
        assert!(te_y_to_x >= 0.0);

        // With a deterministic copy, TE in the causal direction should be detectable
        // At minimum, TE(x->y) should be meaningfully positive
        assert!(
            te_x_to_y > 0.001,
            "TE(x->y) = {:.4} should be meaningfully positive for deterministic coupling",
            te_x_to_y,
        );
    }

    #[test]
    fn test_phase_transfer_entropy_short_signal() {
        let x = vec![1.0, 2.0];
        let y = vec![3.0, 4.0];
        let te = ConnectivityAnalyzer::phase_transfer_entropy(&x, &y, 5);
        assert!((te - 0.0).abs() < 1e-15, "Too-short signal should return 0");
    }

