    #[test]
    fn test_dipole_moment_estimation_accuracy() {
        let (positions, orientations) = test_sensor_array(32, 0.12);

        let true_moment = [1e-9, 2e-9, 0.5e-9];
        let true_source = DipoleSource {
            position: [0.02, 0.0, 0.0],
            moment: true_moment,
            goodness_of_fit: 1.0,
        };

        let measurements =
            MegProcessor::forward_model(&true_source, &positions, &orientations);

        // Grid includes exact position
        let grid = vec![[0.02, 0.0, 0.0]];

        let fitted = MegProcessor::dipole_fit(&measurements, &positions, &orientations, &grid);

        // Moment should match closely
        for i in 0..3 {
            let relative_error = if true_moment[i].abs() > 1e-15 {
                (fitted.moment[i] - true_moment[i]).abs() / true_moment[i].abs()
            } else {
                fitted.moment[i].abs()
            };
            assert!(
                relative_error < 0.01,
                "Moment[{}] relative error = {:.4}, expected < 0.01",
                i,
                relative_error
            );
        }
    }

    /// Helper: compute Goertzel power at a specific frequency.
    fn goertzel_power(signal: &[f64], freq_hz: f64, sample_rate: f64) -> f64 {
        let n = signal.len();
        let k = (freq_hz * n as f64 / sample_rate).round();
        let w = 2.0 * PI * k / n as f64;
        let coeff = 2.0 * w.cos();

        let mut s0 = 0.0;
        let mut s1 = 0.0;
        let mut s2 = 0.0;

        for &x in signal {
            s0 = x + coeff * s1 - s2;
            s2 = s1;
            s1 = s0;
        }

        let real = s1 - s2 * w.cos();
        let imag = s2 * w.sin();
        (real * real + imag * imag) / (n as f64 * n as f64)
    }
